impl Solution {
    pub fn longest_mountain(arr: Vec<i32>) -> i32 {
        let n = arr.len();
        if n < 3 {
            return 0;
        }

        let mut max_len = 0;
        let mut i = 1;

        while i < n - 1 {
            let mut up = 0;
            let mut down = 0;

            // Check if current position is the peak
            if arr[i] > arr[i - 1] {
                // Count the increasing sequence
                while i < n && arr[i] > arr[i - 1] {
                    up += 1;
                    i += 1;
                }
                // Count the decreasing sequence
                while i < n && arr[i] > arr[i - 1] {
                    down += 1;
                    i += 1;
                }
                // Check if we have both increasing and decreasing sequences
                if up > 0 && down > 0 {
                    max_len = max_len.max(up + down + 1);
                }
            } else {
                i += 1;
            }
        }

        max_len
    }
}

